from collections import defaultdict
class Solution:
    def minLength(self, nums, k):
        cnt = defaultdict(int)
        dsum = 0
        ans = float('inf')
        l = 0
        for r, x in enumerate(nums):
            if cnt[x] == 0:
                dsum += x
            cnt[x] += 1
            while dsum >= k:
                ans = min(ans, r - l + 1)
                y = nums[l]
                cnt[y] -= 1
                if cnt[y] == 0:
                    dsum -= y
                l += 1
        return ans if ans != float('inf') else -1

