class Solution {
public:
    int minLength(vector<int>& nums, int k) {
        unordered_map<int, int> cnt;
        long long dsum = 0;
        int ans = INT_MAX, l = 0;
        for (int r = 0; r < (int)nums.size(); r++) {
            if (cnt[nums[r]]++ == 0) dsum += nums[r];
            while (dsum >= k) {
                ans = min(ans, r - l + 1);
                if (--cnt[nums[l]] == 0) dsum -= nums[l];
                l++;
            }
        }
        return ans == INT_MAX ? -1 : ans;
    }
};

