var minLength = function(nums, k) {
    const cnt = new Map();
    let dsum = 0, ans = Infinity, l = 0;
    for (let r = 0; r < nums.length; r++) {
        const x = nums[r];
        const c = (cnt.get(x) || 0) + 1;
        cnt.set(x, c);
        if (c === 1) dsum += x;
        while (dsum >= k) {
            ans = Math.min(ans, r - l + 1);
            const y = nums[l];
            const cy = cnt.get(y) - 1;
            cnt.set(y, cy);
            if (cy === 0) dsum -= y;
            l++;
        }
    }
    return ans === Infinity ? -1 : ans;
};
